-- M3 /five simple maintenance knowledge articles used as evidence.
INSERT INTO knowledge_article (title, category, content) VALUES
                                                             ('Conveyor Motor Overheating Troubleshooting', 'CONVEYOR',
                                                              'Motor overheating can be caused by insufficient ventilation, excessive load, worn bearings, poor lubrication, or electrical overload. Before replacing the motor, inspect airflow, check bearing condition, verify lubrication, and measure current draw.'),

                                                             ('Motor Lubrication Checklist', 'MOTOR',
                                                              'Lubrication issues may increase friction and motor temperature. Check lubricant level, lubricant type, contamination, bearing noise, and maintenance interval history.'),

                                                             ('Pump Vibration Troubleshooting', 'PUMP',
                                                              'Pump vibration may be caused by misalignment, worn bearings, cavitation, loose mounting bolts, or unbalanced rotating components. Inspect alignment, mounting, bearing condition, and flow conditions.'),

                                                             ('Sensor Calibration Guide', 'SENSOR',
                                                              'Unstable sensor readings may result from loose wiring, environmental interference, incorrect calibration, damaged sensor elements, or unstable power supply. Verify wiring, recalibrate the sensor, and check signal stability.'),

                                                             ('Safety Instructions Before Maintenance Intervention', 'SAFETY',
                                                              'Before maintenance intervention, isolate equipment energy sources, follow lockout-tagout procedures, verify zero energy state, wear appropriate PPE, and confirm that the machine cannot restart unexpectedly.');